#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_xcipher;
float4 amzSample_xcipher(float2 uv) { return float4(amzt_xcipher.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xcipher(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_autop;
uniform float amzp_OFFSIDE;
uniform float amzp_PROGRESS;
uniform float amzp_SPEED;
uniform float amzp_glitchAmplitude;
uniform float amzp_AMOUNT;
uniform float amzp_scale;
uniform float2 amzp_stretch;
uniform float amzp_DISTORT;
uniform float amzp_STEP;
uniform float amzp_glitchNarrowness;
uniform float amzp_glitchBlockiness;
uniform float amzp_glitchMinimizer;
uniform float amzp_alpha;
uniform float amzp_rcolor;
uniform float amzp_gcolor;
uniform float amzp_bcolor;
    float4 newLayer( float4 a, float4 b) { return a * (1.0 - b.a) + b; }
    float2x2 rot2m(float a){ float s = sin(a); float c = cos(a); return float2x2(c, -s, s, c); }
    float2 l2s( float2 v ) { return (float4(v,0.,1.0)*amzLayerToScreen()).xy; }
        float rand(float2 p)
        {
            float EVO = (amzp_autop>0.5)? amzp_PROGRESS + (time*amzp_SPEED) : amzp_PROGRESS;
            float t = floor(EVO*10.0) / 10.0;
            return fract(sin(dot(p, float2(t * 12.9898, t * 78.233))) * 43758.5453);
        }
        float noise(float2 uv, float blockiness)
        {
            float2 lv = fract(uv);
            float2 id = floor(uv);
            float n1 = rand(id);
            float n2 = rand(id+float2(1,0));
            float n3 = rand(id+float2(0,1));
            float n4 = rand(id+float2(1,1));
            float2 u = smoothstep(0.0, 1.0 + blockiness, lv);
            return mix(mix(n1, n2, u.x), mix(n3, n4, u.x), u.y);
        }
        float fbm(float2 uv, int count, float blockiness, float complexity)
        {
            float val = 0.0;
            float amp = 0.5;
            while(count != 0)
            {
             val += amp * noise(uv, blockiness);
                amp *= 0.5;
                uv *= complexity;
                count--;
            }
            return val;
        }
        void amzRender() {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float2 iMouse = float2(0.5, 0.5);
        float2 satriyaid;
        satriyaid = amzScreenNorm().st;
     float4 fragColor;
            float2 uv = satriyaid;
            float2 a = float2(uv.x * (iResolution.x / iResolution.y), uv.y);
            float2 uv2 = float2(a.x / iResolution.x, exp(a.y));
            float2 id = floor(uv * amzp_AMOUNT);
                float2 scaleVec;
                scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
                uv2 /= scaleVec;
            float shift = amzp_glitchAmplitude * pow(fbm(uv2, int(rand(id) * amzp_DISTORT),
                          amzp_glitchBlockiness, amzp_glitchNarrowness), amzp_glitchMinimizer);
            float scanline = abs(cos(uv.y * 400.0));
            scanline = smoothstep(0.0, 2.0, scanline);
            shift = smoothstep(0.00001, amzp_STEP, shift);
                float colR;
                if ((amzp_rcolor>0.5)) { colR = amzTexture(0, float2(uv.x + shift, uv.y)).r * (1. - shift); }
                else { colR = amzTexture(0, float2(uv.x - shift, uv.y)).r * (1. - shift); }
                float colG;
                if ((amzp_gcolor>0.5)) { colG = amzTexture(0, float2(uv.x + shift, uv.y)).g * (1. - shift); }
                else { colG = amzTexture(0, float2(uv.x - shift, uv.y)).g * (1. - shift); }
                float colB;
                if ((amzp_bcolor>0.5)) { colB = amzTexture(0, float2(uv.x + shift, uv.y)).b * (1. - shift); }
                else { colB = amzTexture(0, float2(uv.x - shift, uv.y)).b * (1. - shift); }
        float3 f = float3(colR, colG, colB);
        float4 factor = float4(f, texColor.a) * amzp_alpha;
        if((amzp_OFFSIDE>0.5)) { factor *= texColor.a; }
        float4 resultfinal = newLayer(texColor*texColor.a,factor);
     amzOutput = resultfinal;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

